0,"Create a Python script that develops a function to analyze a log file, extract specific patterns based on provided criteria, and generate an aggregated report in a structured format. The function should accept three parameters: the path of the input log file, the desired output file path, and a dictionary containing the search criteria. The script should utilize built-in Python libraries for file handling and parsing, dynamically allocate memory as needed, and efficiently manage resources. The output report should present the extracted data in a readable table format with relevant statistics.",120,,"[""```python
import re
from collections import defaultdict
import pandas as pd

def analyze_log_file(input_path, output_path, search_criteria):
    # Initialize a dictionary to store the extracted data
    extracted_data = defaultdict(list)

    # Open and read the log file
    with open(input_path, 'r') as file:
        for line in file:
            for pattern, criteria in search_criteria.items():
                if re.search(pattern, line):
                    match = re.search(criteria['regex'], line)
                    if match:
                        extracted_data[pattern].append(match.group())

    # Create a DataFrame to store the extracted data
    df = pd.DataFrame(extracted_data)

    # Save the DataFrame to an Excel file
    df.to_excel(output_path, index=False)

# Example usage
search_criteria = {
    'ERROR': {'regex': r'ERROR:\s*(.*)'},
    'WARNING': {'regex': r'WARNING:\s*(.*)'}
}
analyze_log_file('path_to_input_log.log', 'path_to_output_report.xlsx', search_criteria)
