0,"Write a Python function that accepts a list of integers as input and returns the count of unique pairs with distinct prime factors, utilizing a Sieve of Eratosthenes algorithm to efficiently identify primes. The function should also output the duration in seconds taken to compute each pair's prime factors. Assume that the input list contains no repeated elements.",330,,"['```python
import time
from math import sqrt

def sieve_of_eratosthenes(limit):
    is_prime = [True] * (limit + 1)
    p = 2
    while (p ** 2 <= limit):
        if (is_prime[p] == True):
            for i in range(p ** 2, limit + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, limit) if is_prime[p]]
    return prime_numbers

def count_distinct_prime_factors(num, primes_set):
    factor_count = 0
    for prime in primes_set:
        if prime > num:
            break
        if num % prime == 0:
            factor_count += 1
            while num % prime == 0:
                num //= prime
    return factor_count

def unique_prime_factor_pairs(nums):
    max_num = max(nums)
    primes_set = set(sieve_of_eratosthenes(int(sqrt(max_num)) + 1))

    start_time = time.time()
    unique_pairs = set()
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if count_distinct_prime_factors(nums[i], primes_set) != count_distinct_prime_factors(nums[j], primes_set):
                unique_pairs.add((nums[i], nums[j]))

    end_time = time.time()
    duration = end_time - start_time
    return len(unique_pairs), duration

# Example usage:
input_list = [15, 21, 22, 28]
unique_count, duration = unique_prime_factor_pairs(input_list)
print(f""Count of unique pairs with distinct prime factors: {unique_count}"")
print(f""Time taken to compute each pair's prime factors: {duration} seconds"")
```']",36,[0],[],True,0,0,0,

