0,"Create a Python function that generates a random hexadecimal color code of a given length and then applies a specified color transformation algorithm to a provided image file. The output should be the transformed image file with the modified color code, without any additional text or comments.",759,,"[""```python
import random
from PIL import Image

def generate_random_hex_color(length):
    return '#' + ''.join(random.choices('0123456789ABCDEF', k=length))

def apply_color_transformation(image_path, output_path, transformation_type):
    image = Image.open(image_path)
    pixels = image.load()

    for i in range(image.width):
        for j in range(image.height):
            r, g, b = pixels[i, j]

            if transformation_type == 'INVERT':
                pixels[i, j] = (255 - r, 255 - g, 255 - b)
            elif transformation_type == 'GRAYSCALE':
                gray = int(0.3 * r + 0.59 * g + 0.11 * b)
                pixels[i, j] = (gray, gray, gray)

    image.save(output_path)

# Example usage
random_color = generate_random_hex_color(6)
apply_color_transformation('input.jpg', 'output.jpg', 'INVERT')
