import random
import hashlib

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        if not self.head:
            self.head = Node(value)
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = Node(value)

    def traverse(self):
        current = self.head
        while current:
            print(current.value, end="" -> "")
            current = current.next
        print(""None"")

class HashTable:
    def __init__(self, size=10):
        self.size = size
        self.table = [None] * size

    def _hash_function(self, key):
        return int(hashlib.sha256(key.encode()).hexdigest(), 16) % self.size

    def insert(self, key, value):
        hash_index = self._hash_function(key)
        if not self.table[hash_index]:
            self.table[hash_index] = [key, value]
        else:
            for item in self.table[hash_index]:
                if item[0] == key:
                    item[1] = value
                    break
            else:
                self.table[hash_index].append([key, value])

    def search(self, key):
        hash_index = self._hash_function(key)
        if self.table[hash_index]:
            for item in self.table[hash_index]:
                if item[0] == key:
                    return item[1]
        return None

# Main script
linked_list = LinkedList()
hash_table = HashTable()

for _ in range(10):
    value = random.randint(1, 100)
    linked_list.append(value)

print(""Linked List:"")
linked_list.traverse()

for _ in range(5):
    key = ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=random.randint(5, 15)))
    value = random.randint(1, 50)
    hash_table.insert(key, value)

print(""\nHash Table:"")
for item in hash_table.table:
    if item:
        for sub_item in item:
            print(f""{sub_item[0]}: {sub_item[1]}"")

# Free allocated memory (not explicitly needed in Python, but good practice)
del linked_list
del hash_table
