    def generate_certificate(oauth_request):
        private_key = oauth_request.get('private_key')
        certificate = oauth_request.get('certificate')
        encoded_private_key = base64.b64encode(private_key.encode()).decode()
        encoded_certificate = base64.b64encode(certificate.encode()).decode()
        return f""-----BEGIN PRIVATE KEY-----\n{encoded_private_key}\n-----END PRIVATE KEY-----\n-----BEGIN CERTIFICATE-----\n{encoded_certificate}\n-----END CERTIFICATE-----\n""

class GraphEnhancer:
    @staticmethod
    def add_vertices(graph, num_vertices):
        for _ in range(num_vertices):
            vertex_id = random.randint(100000, 999999)
            property1 = random.randint(1, 100)
            property2 = random.choice(['A', 'B', 'C'])
            graph.add_node(vertex_id, id=vertex_id, property1=property1, property2=property2)

    @staticmethod
    def add_edges(graph, num_edges):
        for _ in range(num_edges):
            vertex1 = random.randint(100000, 999999)
            vertex2 = random.randint(100000, 999999)
            weight = round(random.uniform(1.5, 2.5), 2)
            timestamp = datetime.now().isoformat()
            graph.add_edge(vertex1, vertex2, weight=weight, timestamp=timestamp)

class NetworkManager:
    def __init__(self):
        self.graph = {}

    def add_node(self, node_id, **properties):
        if node_id not in self.graph:
            self.graph[node_id] = properties

    def add_edge(self, source, target, **properties):
        if source in self.graph and target in self.graph:
            if 'edges' not in self.graph[source]:
                self.graph[source]['edges'] = {}
            self.graph[source]['edges'][target] = properties

    def integrate_modules(self, oauth_request, num_vertices, num_edges):
        certificate = CertificateGenerator.generate_certificate(oauth_request)
        GraphEnhancer.add_vertices(self.graph, num_vertices)
        GraphEnhancer.add_edges(self.graph, num_edges)
        return certificate, self.graph

# Example usage
network_manager = NetworkManager()
oauth_request = {
    'private_key': 'your_private_key_here',
    'certificate': 'your_certificate_here'
}
certificate, updated_graph = network_manager.integrate_modules(oauth_request, 5, 3)
print(certificate)
print(updated_graph)
