import base64

def decode_base64(encoded_string):
    try:
        # Decode the base64 encoded string
        decoded_bytes = base64.b64decode(encoded_string)
        return decoded_bytes.decode('utf-8')
    except (base64.binascii.Error, UnicodeDecodeError) as e:
        return f""Error decoding: {e}""

def restrict_access(func):
    def wrapper(*args, **kwargs):
        # Restrict access to sensitive system resources
        if not hasattr(decode_base64, 'sensitive_resource_access'):
            decode_base64.sensitive_resource_access = False

        if not decode_base64.sensitive_resource_access:
            return ""Access denied""

        return func(*args, **kwargs)

    return wrapper

# Apply the restriction decorator to the decode_base64 function
decode_base64 = restrict_access(decode_base64)

# Example usage
encoded_string = ""SGVsbG8gV29ybGQh""
print(decode_base64(encoded_string))  # Output: Hello World!

# Restrict access
decode_base64.sensitive_resource_access = True
print(decode_base64(""InvalidBase64""))  # Output: Access denied
