import json

class Registry:
    def __init__(self):
        self._registry = {}

    def register(self, id, factory):
        self._registry[id] = factory

    def get_factory(self, id):
        return self._registry.get(id)

class JsonParser:
    def __init__(self, registry):
        self.registry = registry

    def convert_to_json(self, data):
        return json.dumps(data)

    def create_from_json(self, json_string):
        return json.loads(json_string)

class JsonCreator:
    def __init__(self, registry):
        self.registry = registry

    def create_instance(self, id, data=None):
        factory = self.registry.get_factory(id)
        if not factory:
            raise ValueError(f""No factory found for ID: {id}"")

        if data is None:
            return factory()

        return factory(data)

class FactoryBase:
    @staticmethod
    def create():
        raise NotImplementedError(""Subclasses must implement this method"")

# Subclasses of JsonCreator using the registry to create instances
class UserFactory(FactoryBase):
    @staticmethod
    def create(name=""Default User""):
        return {""name"": name}

factory_registry = Registry()
factory_registry.register(""user"", UserFactory.create)

json_parser = JsonParser(factory_registry)
json_creator = JsonCreator(factory_registry)

data_to_json_str = {""name"": ""John Doe""}
json_str_to_data = '{""name"": ""Jane Doe""}'

converted_json_str = json_parser.convert_to_json(data_to_json_str)
parsed_data_from_json_str = json_parser.create_from_json(json_str_to_data)

new_user_instance_1 = json_creator.create_instance(""user"")
new_user_instance_2 = json_creator.create_instance(""user"", {""name"": ""Alex Smith""})

print(new_user_instance_1)
