import uuid
import unittest

class CUSTOMER_PROFILE_T:
    def __init__(self, name, email):
        self.name = name
        self.email = email
        self.customer_id = uuid.uuid4()

def generate_customers(num_customers):
    customers = []
    try:
        for _ in range(num_customers):
            name = f""Customer{uuid.uuid4()}""
            email = f""{name}@example.com""
            customer = CUSTOMER_PROFILE_T(name, email)
            customers.append(customer)
    except Exception as e:
        print(f""An error occurred: {e}"")
    return customers

class TestGenerateCustomers(unittest.TestCase):
    def test_generate_customers(self):
        num_customers = 5
        customers = generate_customers(num_customers)

        self.assertEqual(len(customers), num_customers, ""The number of customers generated is incorrect."")

