# Mock library for generating customer profiles
class CustomerProfile:
    def __init__(self):
        self.customer_id = str(uuid4())
        self.name = self._generate_random_name()
        self.email = self._generate_random_email()

    @staticmethod
    def _generate_random_name():
        first_names = ['Alice', 'Bob', 'Charlie', 'David', 'Eve']
        last_names = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones']
        return f""{random.choice(first_names)} {random.choice(last_names)}""

    @staticmethod
    def _generate_random_email():
        domains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com']
        return f""{uuid4().hex}@{random.choice(domains)}""

def generate_customers(num_customers):
    customers = []
    for _ in range(num_customers):
        customer = CustomerProfile()
        customers.append(customer)
    return customers

# Unit tests for the generate_customers function
class TestGenerateCustomers(unittest.TestCase):
    def test_number_of_customers(self):
        num_customers = 5
        customers = generate_customers(num_customers)
        self.assertEqual(len(customers), num_customers)

    def test_unique_customer_ids(self):
        num_customers = 10
        customers = generate_customers(num_customers)
        customer_ids = {customer.customer_id for customer in customers}
        self.assertEqual(len(customer_ids), num_customers)

    def test_valid_names_and_emails(self):
        num_customers = 5
        customers = generate_customers(num_customers)
        name_pattern = re.compile(r'^[A-Za-z]+\s[A-Za-z]+$')
        email_pattern = re.compile(r'^\w+@\w+\.\w+$')
        for customer in customers:
            self.assertRegex(customer.name, name_pattern)
            self.assertRegex(customer.email, email_pattern)

if __name__ == '__main__':
    unittest.main()
