import random

class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_bst(root, value):
    if root is None:
        return TreeNode(value)
    if value < root.value:
        root.left = insert_bst(root.left, value)
    else:
        root.right = insert_bst(root.right, value)
    return root

def inorder_traversal(root):
    if root:
        inorder_traversal(root.left)
        print(root.value, end="" "")
        inorder_traversal(root.right)

def preorder_traversal(root):
    if root:
        print(root.value, end="" "")
        preorder_traversal(root.left)
        preorder_traversal(root.right)

def postorder_traversal(root):
    if root:
        postorder_traversal(root.left)
        postorder_traversal(root.right)
        print(root.value, end="" "")

class GraphNode:
    def __init__(self, key):
        self.key = key
        self.neighbors = []

def add_edge(graph, u_key, v_key):
    u = next((node for node in graph if node.key == u_key), None)
    v = next((node for node in graph if node.key == v_key), None)
    if u and v:
        u.neighbors.append(v)
        v.neighbors.append(u)

def dfs(graph, start_key):
    visited = set()
    stack = [start_key]
    while stack:
        vertex_key = stack.pop()
        if vertex_key not in visited:
            visited.add(vertex_key)
            print(vertex_key, end="" "")
            for neighbor in reversed([neighbor.key for neighbor in graph if neighbor.key == vertex_key]):
                if neighbor.key not in visited:
                    stack.append(neighbor.key)

def bfs(graph, start_key):
    visited = set()
    queue = [start_key]
    while queue:
        vertex_key = queue.pop(0)
        if vertex_key not in visited:
            visited.add(vertex_key)
            print(vertex_key, end="" "")
            for neighbor in [neighbor.key for neighbor in graph if neighbor.key == vertex_key]:
                if neighbor.key not in visited and neighbor.key not in queue:
                    queue.append(neighbor.key)

