import os
import re

def categorize_files(directory):
    extensions = {
        'images': 0,
        'documents': 0,
        'archives': 0,
    }

    filenames = os.listdir(directory)

    for filename in filenames:
        if re.search(r'\.(jpg|jpeg|png)$', filename, re.IGNORECASE):
            extensions['images'] += 1
        elif re.search(r'\.(pdf|doc|docx)$', filename, re.IGNORECASE):
            extensions['documents'] += 1
        elif re.search(r'\.(zip|rar)$', filename, re.IGNORECASE):
            extensions['archives'] += 1

    return extensions
