import os
import pandas as pd
from concurrent.futures import ThreadPoolExecutor
import matplotlib.pyplot as plt

def read_csv_files(file_paths):
    data = {}
    for file_path in file_paths:
        if not os.path.exists(file_path) or not file_path.endswith('.csv'):
            raise FileNotFoundError(f""File {file_path} does not exist or is not a CSV file."")

        try:
            df = pd.read_csv(file_path)
            if list(df.columns) != ['Date', 'Open', 'High', 'Low', 'Close']:
                raise ValueError(""CSV file does not have the correct headers."")
            data[file_path] = df
        except Exception as e:
            raise IOError(f""Error reading {file_path}: {e}"")

    return data

def preprocess_data(data):
    for stock, df in data.items():
        df['Date'] = pd.to_datetime(df['Date'])
        df.set_index('Date', inplace=True)
        df.interpolate(method='time', inplace=True)
        df.fillna(method='ffill', inplace=True)
        data[stock] = df
    return data

def calculate_sma(data, window_size):
    for stock, df in data.items():
        df['SMA'] = df['Close'].rolling(window=window_size).mean()
    return data

def save_output(data, output_dir, output_format='csv'):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    for stock, df in data.items():
        file_name = f""{stock.split('/')[-1].split('.')[0]}_SMA.{output_format}""
        output_path = os.path.join(output_dir, file_name)

        if output_format == 'csv':
            df.to_csv(output_path)
        elif output_format == 'json':
            df.to_json(output_path)
        else:
            raise ValueError(f""Unsupported output format: {output_format}"")

def visualize_data(data, window_size):
    for stock, df in data.items():
        plt.figure(figsize=(10, 5))
        plt.plot(df['Close'], label='Original Price')
        plt.plot(df['SMA'], label=f'SMA ({window_size} days)')
        plt.title(f""Stock: {stock.split('/')[-1].split('.')[0]}, SMA ({window_size} days)"")
        plt.xlabel('Date')
        plt.ylabel('Price')
        plt.legend()
        plt.show()

def main(file_paths, output_dir, window_size, output_format='csv'):
    data = read_csv_files(file_paths)
    data = preprocess_data(data)
    data = calculate_sma(data, window_size)
    save_output(data, output_dir, output_format)
    visualize_data(data, window_size)

if __name__ == ""__main__"":
    file_paths = ['path/to/stock1.csv', 'path/to/stock2.csv']
    output_dir = 'output'
    window_size = 10
    main(file_paths, output_dir, window_size)
```

