import base64

def decode_base64(encoded_str, max_tries=3):
    attempts = 0
    while attempts < max_tries:
        try:
            decoded_text = base64.b64decode(encoded_str).decode('utf-8')
            return decoded_text
        except (base64.binascii.Error, UnicodeDecodeError) as e:
            attempts += 1
            if attempts == max_tries:
                return f""Error decoding string: {str(e)}""
            encoded_str = input(""Invalid encoded string. Please enter a valid base64 encoded string: "")
    return ""Failed to decode after multiple attempts.""

def restrict_access(func):
    import os

    def wrapper(*args, **kwargs):
        if os.geteuid() != 0:
            raise PermissionError(""Function requires elevated privileges"")
        return func(*args, **kwargs)
    return wrapper

@restrict_access
def sensitive_function():
