import pandas as pd

def calculate_sma_and_filter_transactions(input_file, output_file, sma_period, max_transaction_age, weight_dict):
    try:
        # Read the input CSV file
        stock_data = pd.read_csv(input_file)

        # Calculate SMA for each stock over the specified period
        stock_data['SMA'] = stock_data.groupby('stock_code')['closing_price'].rolling(window=sma_period).mean()
        sma_output = stock_data[['date', 'stock_code', 'SMA']]
        sma_output.to_csv(output_file, index=False)

        # Filter transactions based on criteria
        filtered_transactions = []
        for index, row in stock_data.iterrows():
            transaction_age = calculate_transaction_age(row['transaction_time'])
            recent_transactions_count = count_recent_transactions(stock_data, row['transaction_id'], max_transaction_age)
            weighted_sum = calculate_weighted_sum(row, weight_dict)

            if transaction_age <= max_transaction_age and recent_transactions_count <= 3:
                filtered_transactions.append({
                    'transaction_id': row['transaction_id'],
                    'weighted_sum': weighted_sum
                })

        # Output comprehensive report
        report = pd.DataFrame(filtered_transactions)
        report.to_csv('filtered_transactions_report.csv', index=False)

    except FileNotFoundError:
        print(""Error: Input file not found."")
    except Exception as e:
        print(f""An error occurred: {e}"")

def calculate_transaction_age(transaction_time):
    # Calculate the age of a transaction in seconds
    current_time = pd.Timestamp.now()
    return (current_time - transaction_time).total_seconds()

def count_recent_transactions(stock_data, transaction_id, max_age):
    # Count transactions within the last 'max_age' seconds
    recent_transactions = stock_data[(stock_data['transaction_id'] != transaction_id) & 
                                    (pd.to_datetime(stock_data['transaction_time']) > pd.to_datetime(transaction_id) - pd.Timedelta(seconds=max_age))]
    return len(recent_transactions)

def calculate_weighted_sum(row, weight_dict):
    # Calculate the weighted sum of transaction attributes
    weighted_sum = 0
    for attribute, weight in weight_dict.items():
        if attribute in row:
            weighted_sum += row[attribute] * weight
    return weighted_sum

# Example usage
calculate_sma_and_filter_transactions('stock_data.csv', 'sma_output.csv', 14, 3600, {'price': 0.5, 'quantity': 0.5})
