import random
import string
from Crypto.Cipher import DES

# Define the NETWORK_EVENTS_T structure
class NETWORK_EVENTS_T:
    def __init__(self, event_id, timestep, event_data_byte_array, event_type):
        self.event_id = event_id
        self.timestep = timestep
        self.event_data_byte_array = event_data_byte_array
        self.event_type = event_type

# Function to generate a random EVENT_ID
def generate_event_id():
    return ''.join(random.choices(string.hexdigits, k=16))

# Function to generate a random TIMESTEP
def generate_timestep():
    return random.randint(0, 2**32 - 1)

# Function to generate a random EVENT_TYPE
def generate_event_type():
    event_types = ['login', 'logout', 'data_access', 'error']
    return random.choice(event_types)

# Function to generate a random byte array of specified length
def generate_byte_array(length):
    return bytes(random.getrandbits(8) for _ in range(length))

# Function to encrypt data using DES encryption
def des_encrypt(data, key):
    cipher = DES.new(key.encode(), DES.MODE_ECB)
    padded_data = data.ljust(len(data) + (8 - len(data)) % 8)
    return cipher.encrypt(padded_data)

# Function to generate and populate a list of NETWORK_EVENTS_T structures
def generate_network_events(num_events, key):
    events = []
    for _ in range(num_events):
        event_id = generate_event_id()
        timestep = generate_timestep()
        event_type = generate_event_type()
        event_data_byte_array = generate_byte_array(16)
        encrypted_data = des_encrypt(event_data_byte_array.decode(), key)
        events.append(NETWORK_EVENTS_T(event_id, timestep, encrypted_data, event_type))
    return events

# Example usage
key = '12345678'  # DES encryption key
num_events = 5
network_events = generate_network_events(num_events, key)

for event in network_events:
    print(f""Event ID: {event.event_id}, Timestep: {event.timestep}, Event Type: {event.event_type}, Encrypted Data: {event.event_data_byte_array}"")
