import pandas as pd
import numpy as np

def analyze_stock_market_data(input_file, output_file, period_days, age_threshold_seconds, transactions_window_seconds):
    try:
        data = pd.read_csv(input_file)

        if 'date' not in data.columns or 'closing_price' not in data.columns:
            raise ValueError(""Invalid input file format. Missing required columns: date, closing_price"")

        data['sma'] = data.groupby('stock')['closing_price'].transform(lambda x: x.rolling(window=period_days).mean())

        filtered_transactions = []
        for index, row in data.iterrows():
            if (row['timestamp'] - row['transaction_time']).total_seconds() <= age_threshold_seconds:
                recent_data = data[(data['timestamp'] >= row['transaction_time'] - pd.Timedelta(seconds=transactions_window_seconds)) & (data['stock'] == row['stock'])]
                if len(recent_data) >= 5:
                    weighted_sum = 2 * row['volume'] + 3 * row['price_change']
                    if weighted_sum > 100:
                        filtered_transactions.append(row)

        sma_output = pd.DataFrame({'date': data.date.unique(), 'sma': np.nan})
        for date in sma_output.date:
            sma_output.loc[sma_output.date == date, 'sma'] = data[data.date == date]['sma'].mean()

        transactions_df = pd.DataFrame(filtered_transactions)

        sma_output.to_csv(output_file + '_sma.csv', index=False)
        transactions_df.to_csv(output_file + '_filtered_transactions.csv', index=False)

    except FileNotFoundError:
        print(""Error: Input file not found."")
    except Exception as e:
        print(f""An error occurred: {e}"")
