2,"Create a Python program that defines a class for handling CSV files. The class should have methods for reading CSV data into memory, writing data to a CSV file, and extracting specific rows based on given criteria. The program should also include a registry of transformation functions, keyed by name, that can be used to manipulate the data before writing it to the CSV file. The task should involve implementing functions for adding new transformation functions to the registry and applying these transformations to the data when writing it to the CSV file.",94,,"[""```python
import csv

class CSVHandler:
    def __init__(self):
        self.transformations = {}

    def register_transformation(self, name, function):
        self.transformations[name] = function

    def apply_transformations(self, data, names):
        for name in names:
            if name in self.transformations:
                data = self.transformations[name](data)
        return data

    def read_csv(self, file_path):
        with open(file_path, mode='r', newline='') as file:
            reader = csv.DictReader(file)
            data = [row for row in reader]
        return data

    def write_csv(self, file_path, data, transformation_names=[]):
        transformed_data = self.apply_transformations(data, transformation_names)
        with open(file_path, mode='w', newline='') as file:
            fieldnames = transformed_data[0].keys()
            writer = csv.DictWriter(file, fieldnames=fieldnames)
            writer.writeheader()
            writer.writerows(transformed_data)

# Example usage
csv_handler = CSVHandler()

def add_column(data):
    for row in data:
        row['new_column'] = 'new_value'
    return data

csv_handler.register_transformation('add_column', add_column)

data = csv_handler.read_csv('input.csv')
csv_handler.write_csv('output.csv', data, ['add_column'])
