from datetime import datetime, timedelta
import random

def generate_api_responses(count, signal_range, quality_range, max_count=100, measurement_frequency=timedelta(seconds=1), add_noise=False):
    if count > max_count:
        raise ValueError(""Count exceeds maximum allowed responses"")

    if not (isinstance(signal_range, tuple) and len(signal_range) == 2):
        raise ValueError(""Signal range must be a tuple of two values"")

    if not (isinstance(quality_range, tuple) and len(quality_range) == 2):
        raise ValueError(""Quality range must be a tuple of two values"")

    responses = []
    for _ in range(count):
        signal_strength = random.uniform(*signal_range)
        quality_score = random.uniform(*quality_range)
        measurement_time = datetime.now() + measurement_frequency * len(responses)

        if add_noise:
            noise_level = random.uniform(-2, 2)  # Adding some noise between -2dB and 2dB
            signal_strength += noise_level

        response = {
            'signal_strength': signal_strength,
            'quality_score': quality_score,
            'measurement_time': measurement_time
        }
        responses.append(response)

    return responses

# Example usage:
try:
    responses = generate_api_responses(count=5, signal_range=(-100, -50), quality_range=(1, 5), add_noise=True)
    for resp in responses:
        print(resp)
except ValueError as e:
    print(e)
