import os
import re

def categorize_files(directory, additional_extensions=None):
    extensions = {
        'images': 0,
        'documents': 0,
        'archives': 0,
        'audio': 0,
        'video': 0,
    }

    if additional_extensions:
        for ext in additional_extensions:
            extensions[ext] = 0

    # Get list of all files in specified directory
    filenames = os.listdir(directory)

    # Categorize files based on their extensions
    for filename in filenames:
        file_ext = os.path.splitext(filename)[1]

        if file_ext and len(file_ext) > 1:
            if re.search(r'\.(jpg|jpeg|png)$', file_ext):
                extensions['images'] += 1
            elif re.search(r'\.(pdf|doc|docx)$', file_ext):
                extensions['documents'] += 1
            elif re.search(r'\.(zip|rar)$', file_ext):
                extensions['archives'] += 1
            elif re.search(r'\.(mp3|m4a)$', file_ext):
                extensions['audio'] += 1
            elif re.search(r'\.(mp4|m4v)$', file_ext):
                extensions['video'] += 1

    return extensions

# Usage example:
