This task combines elements from both prompts by leveraging dynamic data transformation techniques with standard I/O operations in Python, resulting in a more comprehensive solution that accommodates both flexible field mapping configurations and structured data conversion between CSV and JSON formats.",680,,"['```python
import csv
import json
import sys

def read_csv_file(file_name):
    try:
        with open(file_name, mode='r', newline='', encoding='utf-8') as file:
            return list(csv.DictReader(file))
    except FileNotFoundError:
        print(f""Error: The file {file_name} does not exist."")
        sys.exit(1)
    except Exception as e:
        print(f""An error occurred while reading the CSV file: {e}"")
        sys.exit(1)

def parse_field_mapping(mapping_string):
    try:
        return json.loads(mapping_string)
    except json.JSONDecodeError:
        print(""Error: Invalid JSON format for field mapping."")
        sys.exit(1)

def convert_to_json(data, field_mapping):
    json_data = []
    for row in data:
        json_row = {}
        for csv_key, json_key in field_mapping.items():
            if csv_key in row and json_key not in json_row:
                try:
                    # Assuming the values are strings that need to be converted
                    value = json.loads(row[csv_key])
                except (json.JSONDecodeError, ValueError):
                    value = row[csv_key]
                json_row[json_key] = value
        if json_row:  # Only add non-empty rows to the JSON array
            json_data.append(json_row)
    return json_data

def write_json_file(file_name, data):
    try:
        with open(file_name, mode='w', encoding='utf-8') as file:
            json.dump(data, file, indent=4, ensure_ascii=False)
    except Exception as e:
        print(f""An error occurred while writing the JSON file: {e}"")
        sys.exit(1)

def main():
    if len(sys.argv) != 4:
        print(""Usage: python csv_to_json.py <input_csv> <output_json> <field_mapping>"")
        sys.exit(1)

    input_csv = sys.argv[1]
    output_json = sys.argv[2]
    field_mapping_string = sys.argv[3]

    data = read_csv_file(input_csv)
    field_mapping = parse_field_mapping(field_mapping_string)
    json_data = convert_to_json(data, field_mapping)
    write_json_file(output_json, json_data)

if __name__ == ""__main__"":
    main()
```

