The program should be able to accept a directory path as input and recursively process all files within it, performing these tasks efficiently and accurately.",328,,"['```python
import os
import hashlib
import threading
from tqdm import tqdm

def calculate_sha256(file_path):
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            hasher.update(chunk)
    return hasher.hexdigest()

def hash_file_with_progress(file_path):
    file_size = os.path.getsize(file_path)
    progress_bar = tqdm(total=file_size, unit='B', unit_scale=True)
    def update_progress(count):
        progress_bar.update(count)
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(4096)
            if not data:
                break
            yield data
            update_progress(len(data))
    progress_bar.close()

def file_type_identification(file_path):
    _, ext = os.path.splitext(file_path)
    if ext in ['.txt', '.csv', '.log']:
        return 'text'
    elif ext in ['.jpg', '.jpeg', '.png']:
        return 'image'
    elif ext in ['.mp3', '.wav', '.aac']:
        return 'audio'
    else:
        return 'unknown'

def hash_directory(directory_path, max_workers=4):
    threads = []
    for root, _, files in os.walk(directory_path):
        for file in files:
            file_path = os.path.join(root, file)
            if file_type_identification(file_path) != 'unknown':
                thread = threading.Thread(target=lambda fp: calculate_sha256(fp), args=(fp,))
                threads.append(thread)
                thread.start()
    for thread in threads:
        thread.join()

def verify_hash(file_path, provided_hash):
    calculated_hash = calculate_sha256(file_path)
    return calculated_hash == provided_hash

# Example usage
directory_to_hash = '/path/to/directory'
hash_directory(directory_to_hash)
```

