import sqlite3

def execute_sql_batch(sql_queries, connection_object, transactional=False, return_result=False, config=None):
    try:
        if transactional:
            connection_object.begin()

        results = []
        for sql_query, params in sql_queries:
            cursor = connection_object.cursor()
            cursor.execute(sql_query, params)
            if return_result:
                results.append(cursor.fetchall())
            cursor.close()

        if transactional:
            connection_object.commit()

        return results
    except Exception as e:
        if transactional:
            connection_object.rollback()
        raise e
    finally:
        connection_object.close()
