class Database:
    def __init__(self):
        self.tables = {}

    def create_table(self, table_name):
        if table_name in self.tables:
            return f""Table '{table_name}' already exists.""
        self.tables[table_name] = []
        return f""Table '{table_name}' created successfully.""

    def add_record(self, table_name, record):
        if table_name not in self.tables:
            return f""Table '{table_name}' does not exist.""
        self.tables[table_name].append(record)
        return f""Record added to '{table_name}'.""

    def delete_record(self, table_name, record_id):
        if table_name not in self.tables:
            return f""Table '{table_name}' does not exist.""
        records = self.tables[table_name]
        if record_id < len(records):
            del records[record_id]
            return f""Record {record_id} deleted from '{table_name}'.""
        else:
            return f""Invalid record ID for table '{table_name}'.""

    def list_records(self, table_name):
        if table_name not in self.tables:
            return f""Table '{table_name}' does not exist.""
        records = self.tables[table_name]
        return [f""Record {i}: {record}"" for i, record in enumerate(records)]

# Example usage
db = Database()
print(db.create_table(""users""))
print(db.add_record(""users"", {""name"": ""Alice"", ""age"": 30}))
print(db.add_record(""users"", {""name"": ""Bob"", ""age"": 25}))
print(db.list_records(""users""))
print(db.delete_record(""users"", 1))
print(db.list_records(""users""))
```']",0,[0],[],True,0,0,0,

