import os

def create_config_file(env_vars):
    config_content = """"
    for key, value in env_vars.items():
        config_content += f""{key.upper()}={value}\n""

    with open(""web_service_config.env"", ""w"") as file:
        file.write(config_content)

def initialize_service():
