from typing import List, Tuple

def analyze_numbers(input_string: str) -> Tuple[int, int, List[int], int, float]:
    if not input_string:
        return 0, 0, [], 1, 0.0

    numbers = [int(num.strip()) for num in input_string.split(',')]
    even_count = sum(1 for num in numbers if num % 2 == 0)
    odd_sum = sum(num for num in numbers if num % 2 != 0)
    primes = [num for num in numbers if is_prime(num)]
    even_product = product(even_numbers(numbers))

    odd_average = round(odd_sum / len(numbers), 2) if numbers else 0.0

    return even_count, odd_sum, sorted(primes), even_product, odd_average

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def product(numbers: List[int]) -> int:
    result = 1
    for num in numbers:
        result *= num
    return result

def even_numbers(numbers: List[int]) -> List[int]:
    return [num for num in numbers if num % 2 == 0]
