import os
import base64
from Crypto.Cipher import AES, DES, ARC4
from Crypto.Hash import HMAC, SHA256

class SecureDataTransfer:
    def __init__(self, key):
        self.key = key.encode('utf-8')

    def encrypt_data(self, data, mode='AES'):
        if mode == 'AES':
            cipher = AES.new(self.key, AES.MODE_CBC)
            ct_bytes = cipher.encrypt(data)
            iv = base64.b64encode(cipher.iv).decode('utf-8')
            ct = base64.b64encode(ct_bytes).decode('utf-8')
            return f'IV:{iv},Ciphertext:{ct}'
        elif mode == 'DES':
            cipher = DES.new(self.key[:8], DES.MODE_CBC)
            ct_bytes = cipher.encrypt(data)
            iv = base64.b64encode(cipher.iv).decode('utf-8')
            ct = base64.b64encode(ct_bytes).decode('utf-8')
            return f'IV:{iv},Ciphertext:{ct}'
        elif mode == 'RC4':
            cipher = ARC4.new(self.key)
            ct_bytes = cipher.encrypt(data)
            ct = base64.b64encode(ct_bytes).decode('utf-8')
            return f'Ciphertext:{ct}'
        else:
            raise ValueError(""Unsupported encryption mode"")

    def decrypt_data(self, encrypted_data, mode='AES'):
        parts = encrypted_data.split(',')
        iv_str, ct_str = parts[0].split(':')[-1], parts[1].split(':')[-1]
        iv_b64decrypted = base64.b64decode(iv_str)

        if mode == 'AES':
            cipher = AES.new(self.key, AES.MODE_CBC, iv=iv_b64decrypted)
        elif mode == 'DES':
            cipher = DES.new(self.key[:8], DES.MODE_CBC, iv=iv_b64decrypted)
        else:
            raise ValueError(""Unsupported decryption mode"")

        ct_bytes = base64.b64decode(ct_str)
        decrypted_data = cipher.decrypt(ct_bytes).rstrip(b'\0')
        return decrypted_data.decode('utf-8')

    def generate_hmac(self, data):
        h_mac_key = SHA256.new(self.key.encode())
        h_mac_key.update(data.encode())
        return h_mac_key.hexdigest()

    def authenticate_received_data(self, encrypted_data, received_hmac):
        decrypted_data = self.decrypt_data(encrypted_data)
        generated_hmac = self.generate_hmac(decrypted_data)
        return hmac.compare_digest(generated_hmac, received_hmac)
