1,"Create a function in Python that generates a random password of specified length, using a combination of uppercase letters, lowercase letters, digits, and special characters. The function should accept parameters for the desired length of the password and the types of characters to include in it. It should also validate the input parameters to ensure they are within acceptable ranges.",377,,"['```python
import random
import string

def generate_password(length, use_uppercase=True, use_lowercase=True, use_digits=True, use_special=True):
    if length < 1:
        raise ValueError(""Password length must be at least 1."")

    characters = []
    if use_uppercase:
        characters.extend(string.ascii_uppercase)
    if use_lowercase:
        characters.extend(string.ascii_lowercase)
    if use_digits:
        characters.extend(string.digits)
    if use_special:
        characters.extend(string.punctuation)

    if not characters:
        raise ValueError(""At least one character type must be selected."")

    password = ''.join(random.choice(characters) for _ in range(length))
    return password

# Example usage
try:
    print(generate_password(12, use_uppercase=True, use_lowercase=True, use_digits=True, use_special=False))
except ValueError as e:
    print(e)
