def execute_sql_batch(sql_queries, connection_object, transactional=False, return_result=False):
    results = []
    try:
        if transactional:
            connection_object.begin()

        for query, params in sql_queries:
            with connection_object.cursor() as cursor:
                cursor.execute(query, params)
                if return_result:
                    results.append(cursor.fetchall())

        if transactional:
            connection_object.commit()

    except Exception as e:
        if transactional:
            connection_object.rollback()
        raise e
    finally:
        connection_object.close()

    return results
