import json

class JSONHandler:
    _registry = {}

    @classmethod
    def register(cls, id, func):
        cls._registry[id] = func

    @classmethod
    def from_json_string(cls, json_str):
        data = json.loads(json_str)
        factory_id = data.get('id')
        if factory_id in cls._registry:
            return cls._registry[factory_id](data)
        raise ValueError(f""No factory function registered for ID: {factory_id}"")

    @staticmethod
    def to_json_string(data):
        return json.dumps(data)

class SubClass(JSONHandler):
    @classmethod
    def from_data(cls, data):
        # Assume additional data processing here
        return cls()

# Registering the subclass with a specific ID
JSONHandler.register('subclass', SubClass.from_data)
