import random

def generate_and_load_database_entry_list(number_of_entries, data_range, field_limits, data_types, data_file_path):
    # Validate inputs
    if not isinstance(number_of_entries, int) or number_of_entries <= 0:
        raise ValueError(""number_of_entries must be a positive integer"")
    if not isinstance(data_range, tuple) or len(data_range) != 2:
        raise ValueError(""data_range must be a tuple with two numeric elements"")
    if not isinstance(field_limits, tuple) or len(field_limits) != 2:
        raise ValueError(""field_limits must be a tuple with two numeric elements"")
    if not all(isinstance(dt, str) for dt in data_types):
        raise ValueError(""data_types must be a list of strings"")
    if not isinstance(data_file_path, str):
        raise ValueError(""data_file_path must be a string"")

    # Load data from the specified file
    with open(data_file_path, 'r') as file:
        data = [line.strip() for line in file.readlines()]

    max_data_items_per_entry = min(number_of_entries, len(data))

    entries = []
    for _ in range(number_of_entries):
        selected_fields = random.sample(range(field_limits[0], field_limits[1] + 1), random.randint(1, max_data_items_per_entry))
        entry = []
        for field in selected_fields:
            if data_types[field - 1] == 'integer':
                value = random.randint(data_range[0], data_range[1])
            elif data_types[field - 1] == 'float':
                value = round(random.uniform(0, 1), 2)
            entry.append(value)
        entries.append(entry)

    return entries
