import os
import json
import gzip
from datetime import datetime

class FileStorageAnalyzer:
    @staticmethod
    def analyze_storage_usage(directory_path, compression_level=6):
        total_size = 0
        try:
            for root, _, files in os.walk(directory_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    total_size += os.path.getsize(file_path)
        except Exception as e:
            print(f""An error occurred while analyzing storage: {e}"")

        result_json = {
            ""total_size"": total_size,
            ""analysis_time"": datetime.now().isoformat()
        }

        try:
            compressed_data = gzip.compress(json.dumps(result_json).encode('utf-8'), compresslevel=compression_level)
        except Exception as e:
            print(f""An error occurred while compressing the JSON data: {e}"")
            return result_json

        return {
            ""compressed_size"": len(compressed_data),
            ""data"": compressed_data
        }

