import os
import json
import gzip
from datetime import datetime

class FileStorageAnalyzer:
    @staticmethod
    def analyze_storage_usage(directory_path, compression_level=5):
        total_size = 0
        try:
            for root, dirs, files in os.walk(directory_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    total_size += os.path.getsize(file_path)

            json_data = {
                ""directory"": directory_path,
                ""total_size"": total_size,
                ""timestamp"": datetime.now().isoformat()
            }

            with gzip.open('storage_usage.json.gz', 'wb', compresslevel=compression_level) as f:
                f.write(json.dumps(json_data).encode('utf-8'))

            return json_data
        except Exception as e:
            print(f""An error occurred: {e}"")
            return None

# Example usage:
# result = FileStorageAnalyzer.analyze_storage_usage('/path/to/directory', compression_level=6)
