class OctreeNode:
    def __init__(self, capacity: int, feature_size: int):
        self.capacity = capacity
        self.feature_size = feature_size
        self.children = [None] * 8
        self.data = []

    def insert(self, vector: list):
        if len(self.data) == self.capacity:
            self._split()
        else:
            index = self._calculate_index(vector)
            if not self.children[index]:
                self.children[index] = OctreeNode(self.capacity // 2, self.feature_size)
            self.children[index].insert(vector)

    def _calculate_index(self, vector: list) -> int:
        index = 0
        for value in vector:
            index <<= 1
            if value > (self.feature_size / 2):
                index |= 1
        return index

    def search(self, vector: list) -> bool:
        index = self._calculate_index(vector)
        if not self.children[index]:
            return False
        else:
            return self.children[index].search(vector)

    def _split(self):
        for i in range(8):
            if self.children[i]:
                for data in self.children[i].data:
                    self.insert(data)
                self.children[i] = None
        self.data.clear()

