0,"Design and implement a program that accepts command-line arguments to perform various actions on an input file. The actions include calculating the file's size in bytes, listing all unique words found in the file, and displaying a histogram of word frequencies. The program should support these options: --size to measure file size, -u to list unique words, -f to display word frequency histogram, and -h for displaying usage instructions.",121,,"['```python
import sys

def get_file_size(file_path):
    return os.path.getsize(file_path)

def list_unique_words(file_path):
    with open(file_path, 'r') as file:
        words = set(word.strip() for line in file for word in line.split())
    return words

def display_word_frequency_histogram(file_path):
    import collections
    with open(file_path, 'r') as file:
        words = [word.strip() for line in file for word in line.split()]
    frequency = collections.Counter(words)
    for word, count in frequency.items():
        print(f'{word}: {""*"" * count}')

def show_usage():
    print(""Usage: python script.py [options] <file_path>"")
    print(""--size\t\tMeasure the file size in bytes"")
    print(""-u\t\tList all unique words found in the file"")
    print(""-f\t\tDisplay a histogram of word frequencies"")
    print(""-h\t\tDisplay usage instructions"")

if __name__ == ""__main__"":
    if len(sys.argv) < 3:
        show_usage()
        sys.exit(1)

    action = sys.argv[1]
    file_path = sys.argv[2]

    if action == ""--size"":
        print(f""File size: {get_file_size(file_path)} bytes"")
    elif action == ""-u"":
        unique_words = list_unique_words(file_path)
        for word in sorted(unique_words):
            print(word)
    elif action == ""-f"":
        display_word_frequency_histogram(file_path)
    elif action == ""-h"":
        show_usage()
    else:
        print(""Invalid action. Use -h to see help."")
```']",3,[0],[],True,0,0,0,

0,"Design and implement a program that utilizes a secure encryption method for password storage and retrieval. The program should include an EncryptionManager class that initializes an AES-256-CBC encryption algorithm using a SHA-256 hash of the user's provided password. This class should offer methods for encrypting and decrypting sensitive data, ensuring that passwords are securely stored and accessible only when correctly decrypted with the user's password. Additionally, the program should incorporate a FileSecurityModule class, which manages file operations by encrypting files before storing them on disk and decrypting them when needed. This module should also be able to modify filenames based on specific criteria, enhancing file organization within the system. Finally, demonstrate the effectiveness of your implementation by encrypting sample data and passwords, storing encrypted files securely, and retrieving the original data upon decryption with the correct password.",327,,"[""```python
import os
from Crypto.Cipher import AES
from Crypto.Hash import SHA256
from Crypto.Util.Padding import pad, unpad

class EncryptionManager:
    def __init__(self, password):
        password_hash = SHA256.new(password.encode()).digest()
        self.key = password_hash[:32]  # AES-256 key
        iv = os.urandom(16)
        self.cipher = AES.new(self.key, AES.MODE_CBC, iv)

    def encrypt(self, data):
        return self.iv + self.cipher.encrypt(pad(data.encode(), AES.block_size))

    def decrypt(self, encrypted_data):
        iv = encrypted_data[:16]
        cipher = AES.new(self.key, AES.MODE_CBC, iv)
        return unpad(cipher.decrypt(encrypted_data[16:]), AES.block_size).decode()

class FileSecurityModule:
    @staticmethod
    def encrypt_file(file_path, password_manager):
        with open(file_path, 'rb') as file:
            data = file.read()
        encrypted_data = password_manager.encrypt(data)
        with open(file_path + '.enc', 'wb') as file:
            file.write(encrypted_data)

    @staticmethod
    def decrypt_file(file_path, password_manager):
        with open(file_path, 'rb') as file:
            encrypted_data = file.read()
        decrypted_data = password_manager.decrypt(encrypted_data)
        with open(file_path[:-4], 'wb') as file:
            file.write(decrypted_data)

    @staticmethod
def rename_files(directory, old_suffix, new_suffix):
    for filename in os.listdir(directory):
        if filename.endswith(old_suffix):
            new_filename = filename.replace(old_suffix, new_suffix)
            os.rename(os.path.join(directory, filename), os.path.join(directory, new_filename))

# Example usage:
password_manager = EncryptionManager('my_secure_password')
sample_data = 'This is a secret message.'
encrypted_data = password_manager.encrypt(sample_data)

file_security_module = FileSecurityModule()
file_security_module.encrypt_file('example.txt', password_manager)
FileSecurityModule.decrypt_file('example.txt.enc', password_manager)
rename_files('.', '.txt', '_encrypted.txt')

