    auth_url = f'https://auth.provider.com/authorize?response_type=code&client_id={client_id}&redirect_uri={redirect_uri}'
    code = input(f'Visit {auth_url} and enter the authorization code: ')

    token_url = 'https://auth.provider.com/token'
