0,"Design a Python function responsible for generating an array of GPSR_Response_T structures. Each structure should contain a valid GPSR_Packet with a randomly generated NID and a status field set to either 'Success' or 'Failure'. The function should employ standard Python libraries for this task and only output the resulting code, excluding any introductory or concluding remarks.",680,,"[""```python
import random

class GPSR_Packet:
    def __init__(self, nid):
        self.nid = nid

class GPSR_Response_T:
    def __init__(self, packet, status):
        self.packet = packet
        self.status = status

def generate_gpsr_responses(count):
    responses = []
    for _ in range(count):
        nid = random.randint(1000, 9999)
        status = random.choice(['Success', 'Failure'])
        packet = GPSR_Packet(nid)
        response = GPSR_Response_T(packet, status)
        responses.append(response)
    return responses
