import hashlib
import pymysql
from json import dumps

def secure_user_management(connection_string, db_name, request):
    def validate_data(data):
        return 'name' in data and 'email' in data and 'password' in data

    def save_data(data):
        query = ""INSERT INTO users (name, email) VALUES (%s, %s) ON DUPLICATE KEY UPDATE password=%s""
        with connection.cursor() as cursor:
            cursor.execute(query, (data['name'], data['email'], hashlib.sha256(data['password'].encode()).hexdigest()))
            connection.commit()

    def update_user(data):
        id = int(data['id'])
        query = ""UPDATE users SET name=%s, email=%s WHERE id=%s""
        with connection.cursor() as cursor:
            cursor.execute(query, (data['name'], data['email'], id))
            connection.commit()

    def delete_user(id):
        query = ""DELETE FROM users WHERE id=%s""
        with connection.cursor() as cursor:
            cursor.execute(query, (id,))
            connection.commit()

    def process_user_data(request_data):
        if validate_data(request_data) and request_data.get('sub_action') == 'create':
            save_data(request_data)
            return {'message': 'success'}

        if request_data.get('sub_action') == 'update':
            update_user(request_data)
            return {'message': 'success'}

        if request_data.get('sub_action') == 'delete':
            delete_user(int(request_data.get('id')))
            return {'message': 'success'}

    conn = pymysql.connect(host=connection_string[0], user=connection_string[1], password=connection_string[2], database=db_name)

    request_output = process_user_data(request)

    conn.close()

    return request_output
