1,"Develop a new function that processes a JSON string input. The function should parse the JSON string and validate its structure according to a specified schema. If the input is valid, the function should extract specific data fields based on provided keys. If the input is invalid, it should return an error message indicating the validation failure details. The function should also include error handling for cases where the keys are not found in the parsed JSON object.",590,,"['```python
import json

def process_json(json_string, schema, keys):
    try:
        data = json.loads(json_string)

        # Validate JSON structure according to the schema
        if not isinstance(data, dict):
            return ""Error: JSON is not a dictionary""

        for key in schema:
            if key not in data or not isinstance(data[key], schema[key]):
                return f""Error: Invalid value for '{key}' in JSON""

        # Extract specific data fields based on provided keys
        extracted_data = {key: data.get(key, None) for key in keys}

        return extracted_data

    except json.JSONDecodeError:
        return ""Error: Invalid JSON format""

# Example usage
json_string = '{""name"": ""John"", ""age"": 30, ""city"": ""New York""}'
schema = {'name': str, 'age': int, 'city': str}
keys = ['name', 'age']

result = process_json(json_string, schema, keys)
print(result)  # Output: {'name': 'John', 'age': 30}
