import random

def generate_and_process_gatt_descriptors(list_size, start_handle=1, callback=None):
    if list_size <= 0:
        raise ValueError(""List size must be greater than 0"")

    descriptors = []
    for i in range(start_handle - 1, start_handle + list_size * 3):
        service_uuid = random.randint(0x0000, 0xFFFF)
        descriptor_uuid = random.randint(0x0000, 0xFFFF)
        characteristic_handle = i
        descriptors.append((service_uuid, descriptor_uuid, characteristic_handle))

    if len(descriptors) != list_size * 3:
        raise ValueError(""Failed to generate all descriptors"")

    for desc in descriptors:
        if callback:
            callback(desc)

def process_descriptor(service_desc):
    print(f""Service UUID: {service_desc[0]}, Descriptor UUID: {service_desc[1]}, Characteristic Handle: {service_desc[2]}"")

# Example usage
generate_and_process_gatt_descriptors(5, start_handle=2, callback=process_descriptor)
