import hashlib
import bcrypt

def validate_and_hash_passwords(passwords_list, hash_algorithm):
    results = {}

    def validate_password(password):
        if len(password) < 8:
            return ""Too short""
        elif not any(char.isupper() for char in password):
            return ""No uppercase letter""
        elif not any(char.islower() for char in password):
            return ""No lowercase letter""
        elif not any(char.isdigit() for char in password):
            return ""No digit""
        elif not any(not char.isalnum() for char in password):
            return ""No special character""
        return None

    for password in passwords_list:
        validation_error = validate_password(password)
        if validation_error:
            results[password] = {""Status"": ""Invalid"", ""Error"": validation_error}
        else:
            try:
                if hash_algorithm == 'bcrypt':
                    hashed_password = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
                elif hash_algorithm == 'sha256':
                    hasher = hashlib.sha256()
                    hasher.update(password.encode('utf-8'))
                    hashed_password = hasher.hexdigest()
                elif hash_algorithm == 'md5':
                    hasher = hashlib.md5()
                    hasher.update(password.encode('utf-8'))
                    hashed_password = hasher.hexdigest()
                else:
                    results[password] = {""Status"": ""Invalid"", ""Error"": f""Unsupported hashing algorithm: {hash_algorithm}""}
                    continue
                results[password] = {""Status"": ""Valid"", ""Hashed Password"": hashed_password.decode('utf-8')}
            except Exception as e:
                results[password] = {""Status"": ""Invalid"", ""Error"": str(e)}

    return results

