import re
import bcrypt
import hashlib

def validate_password(password):
    if len(password) < 8:
        return ""Invalid"", ""Password length must be at least 8 characters""
    if not re.search(""[A-Z]"", password):
        return ""Invalid"", ""Password must contain at least one uppercase letter""
    if not re.search(""[a-z]"", password):
        return ""Invalid"", ""Password must contain at least one lowercase letter""
    if not re.search(""[0-9]"", password):
        return ""Invalid"", ""Password must contain at least one digit""
    if not re.search(""[!@#$%^&*(),.?\"":{}|<>]"", password):
        return ""Invalid"", ""Password must contain at least one special character""
    return ""Valid"", None

def hash_password(password, hash_algorithm):
    errors = []

    if hash_algorithm == 'bcrypt':
        try:
            salt = bcrypt.gensalt()
            hashed_password = bcrypt.hashpw(password.encode('utf-8'), salt)
            return hashed_password.decode('utf-8'), None
        except Exception as e:
            errors.append(str(e))

    elif hash_algorithm in ['sha256', 'md5']:
        try:
            hashed_password = hashlib.new(hash_algorithm, password.encode('utf-8')).hexdigest()
            return hashed_password, None
        except Exception as e:
            errors.append(str(e))

    else:
        errors.append(""Unsupported hashing algorithm"")

    if errors:
        raise ValueError(errors)

def validate_and_hash_passwords(passwords_list, hash_algorithm):
    results = {}

    for password in passwords_list:
        validation_status, validation_error = validate_password(password)

        if validation_status == 'Valid':
            try:
                hashed_password, hashing_error = hash_password(password, hash_algorithm)
                results[password] = {'status': validation_status, 'hashed': True}
                results[password]['hash'] = hashed_password
                results[password]['error'] = hashing_error or None

            except ValueError as e:
                results[password] = {'status': validation_status, 'hashed': False}
                results[password]['error'] = str(e)

            except Exception as e:
                results[password] = {'status': validation_status, 'hashed': False}
                results[password]['error'] = str(e)

        else:
            results[password] = {'status': validation_status, 'hashed': False}

    return results
```

