import random
import string

def generate_unique_list(n, min_age, max_age):
    if n > 100:
        raise ValueError(""Maximum number of entries should not exceed 100"")

    if min_age < 0 or max_age < min_age:
        raise ValueError(""Invalid age range"")

    names = set()
    ages = set()

    for _ in range(n):
        while True:
            name = ''.join(random.choices(string.ascii_letters + string.digits, k=random.randint(5, 15)))
            if name not in names:
                break

        while True:
            age = random.randint(min_age, max_age)
            if age not in ages:
                break

        names.add(name)
        ages.add(age)

        yield {'name': name, 'age': age}

# Example usage
entries = list(generate_unique_list(5, 18, 60))
print(entries)
