1,"Create a Python script for handling and analyzing text data with command-line interface support. Implement features to extract email addresses, URLs, and phone numbers from an input text file. Use `argparse` for parsing command-line options. Define options like `-e` for extracting emails, `-u` for URLs, `-p` for phone numbers, and `-o` for output file name to save the extracted data.",328,,"['```python
import argparse
import re

def extract_emails(text):
    return re.findall(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', text)

def extract_urls(text):
    return re.findall(r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+', text)

def extract_phone_numbers(text):
    return re.findall(r'\b\d{3}[-.\s]?\d{3}[-.\s]?\d{4}\b', text)

def main():
    parser = argparse.ArgumentParser(description='Text data handler with command-line interface.')
    parser.add_argument('input_file', type=str, help='Input text file name')
    parser.add_argument('-e', action='store_true', help='Extract emails')
    parser.add_argument('-u', action='store_true', help='Extract URLs')
    parser.add_argument('-p', action='store_true', help='Extract phone numbers')
    parser.add_argument('-o', type=str, help='Output file name to save the extracted data')

    args = parser.parse_args()

    with open(args.input_file, 'r') as file:
        text = file.read()

    results = {}
    if args.e:
        results['emails'] = extract_emails(text)
    if args.u:
        results['urls'] = extract_urls(text)
    if args.p:
        results['phone_numbers'] = extract_phone_numbers(text)

    if args.o:
        with open(args.o, 'w') as output_file:
            for key, value in results.items():
                output_file.write(f'{key.upper()}: {"", "".join(value)}\n')

if __name__ == '__main__':
    main()
