0,"Design and implement a simplified version of a text-based game engine in Python. The engine should enable users to create, load, and save game scenarios. Users should be able to add, modify, and delete game elements such as characters, items, and locations within a scenario. Focus on code organization by implementing separate modules for game elements and scenario management. Ensure the system provides clear error messages for invalid user inputs or actions without crashing the program. The engine should also offer basic search functionality to help users find specific elements within their scenarios efficiently.",345,,"['```python
# game_elements.py

class Character:
    def __init__(self, name):
        self.name = name

class Item:
    def __init__(self, name):
        self.name = name

class Location:
    def __init__(self, name):
        self.name = name

# scenario_manager.py

import json
from game_elements import Character, Item, Location

class ScenarioManager:
    def __init__(self, filename='game_scenario.json'):
        self.filename = filename
        self.scenario = {'characters': [], 'items': [], 'locations': []}

    def load_scenario(self):
        try:
            with open(self.filename, 'r') as file:
                self.scenario = json.load(file)
        except FileNotFoundError:
            print(""No scenario found. Starting a new one."")

    def save_scenario(self):
        with open(self.filename, 'w') as file:
            json.dump(self.scenario, file, indent=4)

    def add_element(self, element_type, name):
        if element_type == 'character':
            self.scenario['characters'].append(Character(name))
        elif element_type == 'item':
            self.scenario['items'].append(Item(name))
        elif element_type == 'location':
            self.scenario['locations'].append(Location(name))
        else:
            print(""Invalid element type."")

    def remove_element(self, element_type, name):
        if element_type == 'character':
            self.scenario['characters'] = [c for c in self.scenario['characters'] if c.name != name]
        elif element_type == 'item':
            self.scenario['items'] = [i for i in self.scenario['items'] if i.name != name]
        elif element_type == 'location':
            self.scenario['locations'] = [l for l in self.scenario['locations'] if l.name != name]
        else:
            print(""Invalid element type."")

    def search_element(self, element_type, keyword):
        if element_type == 'character':
            return [c for c in self.scenario['characters'] if keyword.lower() in c.name.lower()]
        elif element_type == 'item':
            return [i for i in self.scenario['items'] if keyword.lower() in i.name.lower()]
        elif element_type == 'location':
            return [l for l in self.scenario['locations'] if keyword.lower() in l.name.lower()]
        else:
            print(""Invalid element type."")
            return []
```

